25	/**
26	 * Assigns a customerCode '<LAST3>-<NNNN>' to each newly-created owner just before it is
27	 * saved: LAST3 is the upper-cased first three letters of the last name and NNNN is a global
28	 * 4-digit sequence equal to one more than the current number of owners. Kept as its own small
29	 * aspect so this rule stays a self-contained unit rather than growing the controller or service.
30	 */
31	@Aspect
32	@Component
33	public class OwnerCustomerCodeAdvice {
34	
35	    private final OwnerRepository ownerRepository;
36	
37	    public OwnerCustomerCodeAdvice(OwnerRepository ownerRepository) {
38	        this.ownerRepository = ownerRepository;
39	    }
40	
41	    @Before("execution(* org.springframework.samples.petclinic.service.ClinicService.saveOwner(..)) && args(owner)")
42	    public void assignCustomerCode(Owner owner) {
43	        if (owner.isNew() && owner.getCustomerCode() == null) {
44	            String last3 = (owner.getLastName() + "XXX").substring(0, 3).toUpperCase();
45	            owner.setCustomerCode(String.format("%s-%04d", last3, ownerRepository.findAll().size() + 1));
46	        }
47	    }
48	}
